<?php

declare(strict_types=1);namespace Acorn\SafetyHealthcheck\Admin;use Acorn\SafetyHealthcheck\Database\Schema;
final class AssessmentsPage{public function render():void{if(!current_user_can('manage_acorn_healthcheck'))wp_die('Forbidden',403);global$wpdb;if(isset($_GET['export'])){$this->export();return;}if(!empty($_GET['assessment'])){$this->detail(absint($_GET['assessment']));return;}$where=['1=1'];$args=[];foreach(['status','jurisdiction','sector']as$field)if(!empty($_GET[$field])){$where[]="a.$field=%s";$args[]=sanitize_text_field(wp_unslash($_GET[$field]));}$sql='SELECT a.id,a.status,a.jurisdiction,a.sector,a.priority_count,a.review_count,a.completed_at,c.company,c.audit_requested FROM '.Schema::table('assessments').' a LEFT JOIN '.Schema::table('contacts').' c ON c.id=a.contact_id WHERE '.implode(' AND ',$where).' ORDER BY a.id DESC LIMIT 100';$rows=$args?$wpdb->get_results($wpdb->prepare($sql,$args),ARRAY_A):$wpdb->get_results($sql,ARRAY_A);echo'<div class="wrap"><h1>Assessments</h1><form method="get"><input type="hidden" name="page" value="acorn-healthcheck-assessments"><input name="jurisdiction" placeholder="Jurisdiction" value="'.esc_attr($_GET['jurisdiction']??'').'"><input name="sector" placeholder="Sector" value="'.esc_attr($_GET['sector']??'').'"><select name="status"><option value="">All statuses</option><option>in_progress</option><option>assessed</option><option>completed</option></select>';submit_button('Filter','secondary','',false);echo'</form><p><a href="'.esc_url(wp_nonce_url(add_query_arg('export','csv'),'acorn_hc_export')).'">Export CSV</a></p><table class="widefat"><thead><tr><th>Company</th><th>Status</th><th>Jurisdiction</th><th>Sector</th><th>Findings</th><th>Actions</th></tr></thead><tbody>';foreach($rows as$r)echo'<tr><td>'.esc_html($r['company']?:'Anonymous').'</td><td>'.esc_html($r['status']).'</td><td>'.esc_html($r['jurisdiction']).'</td><td>'.esc_html($r['sector']).'</td><td>'.(int)$r['priority_count'].' priority, '.(int)$r['review_count'].' review</td><td><a href="'.esc_url(add_query_arg('assessment',(int)$r['id'])).'">Overview / Answers / Recommendations / Contact / Report</a></td></tr>';echo'</tbody></table></div>';}
private function detail(int$id):void{global$wpdb;$a=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Schema::table('assessments').' WHERE id=%d',$id),ARRAY_A);if(!$a){echo'<div class="wrap"><p>Assessment not found.</p></div>';return;}$answers=$wpdb->get_results($wpdb->prepare('SELECT question_key,answer_value,finding_status,answered_at FROM '.Schema::table('answers').' WHERE assessment_id=%d ORDER BY id',$id),ARRAY_A);$contact=$a['contact_id']?$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Schema::table('contacts').' WHERE id=%d',$a['contact_id']),ARRAY_A):[];echo'<div class="wrap"><h1>Assessment #'.(int)$id.'</h1><nav class="nav-tab-wrapper"><a class="nav-tab nav-tab-active">Overview</a><a class="nav-tab">Answers</a><a class="nav-tab">Recommendations</a><a class="nav-tab">Contact</a><a class="nav-tab">Report</a></nav><h2>Overview</h2><p>'.esc_html($a['overall_status']?:$a['status']).' — '.(int)$a['priority_count'].' priority, '.(int)$a['review_count'].' review, '.(int)$a['addressed_count'].' addressed</p><h2>Answers &amp; recommendations</h2><table class="widefat"><tr><th>Question</th><th>Answer</th><th>Finding</th></tr>';foreach($answers as$x)echo'<tr><td>'.esc_html($x['question_key']).'</td><td>'.esc_html($x['answer_value']).'</td><td>'.esc_html($x['finding_status']).'</td></tr>';echo'</table><h2>Contact</h2><p>'.esc_html(($contact['first_name']??'').' '.($contact['last_name']??'').' · '.($contact['email']??'')).'</p><h2>Report</h2><p><a class="button" href="'.esc_url(wp_nonce_url(admin_url('admin-post.php?action=acorn_hc_pdf&assessment='.$id),'acorn_hc_pdf_'.$id)).'">Download PDF</a> <a class="button" href="'.esc_url(wp_nonce_url(admin_url('admin-post.php?action=acorn_hc_resend&assessment='.$id),'acorn_hc_resend_'.$id)).'">Resend report</a></p><p>Delivery status: '.esc_html($a['email_status']).'; PDF: '.esc_html($a['pdf_status']).'.</p></div>';}

public function downloadPdf():void{if(!current_user_can('manage_acorn_healthcheck'))wp_die('Forbidden',403);$id=absint($_GET['assessment']??0);check_admin_referer('acorn_hc_pdf_'.$id);$data=(new \Acorn\SafetyHealthcheck\Reports\ReportDataBuilder())->build($id);(new \Acorn\SafetyHealthcheck\Reports\PdfGenerator())->stream($data,'Acorn-Healthcheck-'.$id.'.pdf');exit;}
public function resend():void{if(!current_user_can('manage_acorn_healthcheck'))wp_die('Forbidden',403);$id=absint($_GET['assessment']??0);check_admin_referer('acorn_hc_resend_'.$id);global$wpdb;$raw=\Acorn\SafetyHealthcheck\Assessment\AssessmentRepository::token();$wpdb->update(Schema::table('assessments'),['report_token_hash'=>hash('sha256',$raw)],['id'=>$id]);$url=home_url('/healthcheck/report/'.rawurlencode($raw).'/');(new \Acorn\SafetyHealthcheck\Notifications\CustomerMailer())->send($id,$url);wp_safe_redirect(admin_url('admin.php?page=acorn-healthcheck-assessments&assessment='.$id));exit;}
private function export():void{check_admin_referer('acorn_hc_export');global$wpdb;$rows=$wpdb->get_results('SELECT a.id,a.status,a.jurisdiction,a.sector,a.priority_count,a.review_count,a.addressed_count,a.completed_at,c.company,c.email,c.audit_requested FROM '.Schema::table('assessments').' a LEFT JOIN '.Schema::table('contacts').' c ON c.id=a.contact_id ORDER BY a.id DESC',ARRAY_A);header('Content-Type:text/csv');header('Content-Disposition:attachment; filename=healthcheck-assessments.csv');$out=fopen('php://output','wb');if($rows){fputcsv($out,array_keys($rows[0]));foreach($rows as$row)fputcsv($out,$row);}fclose($out);exit;}}
